using System.Diagnostics;
using System.Security.Principal;
using System.Text.Json;
using Microsoft.Win32;
namespace CodexLight.Migration;
public sealed record StageReceipt(string Phase,LegacyInstall Legacy,string NewRoot,string ManifestSha256,string SetupSha256,string Target,string Recovery){public string HandoffPlan {get;init;}="";public string HandoffPlanSha256 {get;init;}="";public string PreHandoffSnapshot {get;init;}="";public string PreHandoffSnapshotSha256 {get;init;}="";public string SourceFailedReceipt {get;init;}="";public string SourceFailedReceiptSha256 {get;init;}="";public string ReconciledSnapshot {get;init;}="";public string ReconciledSnapshotSha256 {get;init;}="";public string ReconciledHealthPath {get;init;}="";public string ReconciledHealthSha256 {get;init;}="";}
public sealed record GuiObservation(string ReceiptSha256,string ManifestSha256,string ExeSha256,int ProcessId,DateTime StartUtc,DateTime ObservedUtc,bool WindowResponding,bool UserConfirmedRealUse);
public static class SafeRetire {
 static readonly JsonSerializerOptions Json=new(){PropertyNameCaseInsensitive=true,WriteIndented=true};
 static T Read<T>(string path)=>JsonSerializer.Deserialize<T>(File.ReadAllText(MigrationStorage.Canonical(path)),Json)??throw new IOException("Evidence absent");
 internal static void ValidateReceipt(StageReceipt r,string receipt,string manifest,string setup){var local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);var expected=Path.Combine(local,"CodexLightDesktop");var recovery=MigrationStorage.Canonical(r.Recovery);var allowed=Path.Combine(local,"CodexLightMigration")+"\\";if(r.Phase!="StagedOldPreserved"||r.ManifestSha256!=manifest||r.SetupSha256!=setup||!r.NewRoot.Equals(expected,StringComparison.OrdinalIgnoreCase)||!recovery.StartsWith(allowed,StringComparison.OrdinalIgnoreCase)||Path.GetDirectoryName(MigrationStorage.Canonical(receipt))!=recovery||r.Legacy.UpgradeCode!=MigrationCoordinator.UpgradeCode)throw new IOException("Stage receipt identity/scope mismatch");}
 static (StageReceipt,StageRelease) Inspect(string receipt,string manifestPath,string manifestHash,string setupHash){SafeStage.Execute(manifestPath,manifestHash,setupHash,false,true,false);var r=Read<StageReceipt>(receipt);ValidateReceipt(r,receipt,manifestHash,setupHash);ManualReconcile.ValidateChain(r);if(MsiProbe.ReadCurrentUser()!=r.Legacy)throw new IOException("Old MSI differs from stage receipt");var m=Read<StageRelease>(manifestPath);if(m.Version!=r.Target)throw new IOException("Receipt target version mismatch");var current=Path.Combine(r.NewRoot,"current");SafeStage.VerifyFiles(current,m.PayloadFiles,true);SafeStage.PackageIdentity(current,m);SafeStage.Registration(r.NewRoot,m);if(MigrationCoordinator.Hash(Path.Combine(r.NewRoot,"Update.exe"))!=m.RootUpdaterSha256||MigrationCoordinator.Hash(SafeStage.Member(r.NewRoot,m.RootStubPath))!=m.RootStubSha256)throw new IOException("Installed root executables differ");return(r,m);}
 public static void ObserveGui(string receipt,string manifestPath,string manifestHash,string setupHash,bool realUseConfirmed){if(!realUseConfirmed)throw new IOException("Explicit user acceptance of real GUI use required; component health is insufficient");var(r,m)=Inspect(receipt,manifestPath,manifestHash,setupHash);string exe=Path.Combine(r.NewRoot,"current","CodexLight.exe");var matches=new List<Process>();foreach(var p in Process.GetProcessesByName("CodexLight")){try{if(string.Equals(p.MainModule?.FileName,exe,StringComparison.OrdinalIgnoreCase))matches.Add(p);else p.Dispose();}catch{p.Dispose();throw new IOException("GUI process identity uncertain");}}try{if(matches.Count!=1||matches[0].MainWindowHandle==IntPtr.Zero||!matches[0].Responding)throw new IOException("Exactly one responsive real new GUI must be observed running");var p=matches[0];var evidence=new GuiObservation(MigrationCoordinator.Hash(receipt),manifestHash,MigrationCoordinator.Hash(exe),p.Id,p.StartTime.ToUniversalTime(),DateTime.UtcNow,true,true);var output=Path.Combine(r.Recovery,"gui-observation.json");if(File.Exists(output))throw new IOException("GUI evidence already exists; inspect rather than overwrite");MigrationStorage.AtomicReceipt(output,evidence);Console.WriteLine(output);}finally{foreach(var p in matches)p.Dispose();}}
 internal static void ValidateObservation(GuiObservation e,string receiptHash,string manifestHash,string exeHash){if(e.ReceiptSha256!=receiptHash||e.ManifestSha256!=manifestHash||e.ExeSha256!=exeHash||!e.WindowResponding||!e.UserConfirmedRealUse||e.StartUtc>e.ObservedUtc||e.ObservedUtc>DateTime.UtcNow.AddMinutes(1)||e.ProcessId<=0)throw new IOException("GUI acceptance does not match this staged build");}
 // Creates a distinct user shortcut, never overwrites old/unknown links. Must be explicitly requested.
 public static void Shortcut(string receipt,string manifestPath,string manifestHash,string setupHash){var(r,m)=Inspect(receipt,manifestPath,manifestHash,setupHash);var directory=MigrationStorage.Canonical(Environment.GetFolderPath(Environment.SpecialFolder.Programs));var path=Path.Combine(directory,"Codex Light (Velopack).lnk");if(File.Exists(path)||Directory.Exists(path))throw new IOException("Shortcut exists; ownership not assumed");string temporary=Path.Combine(directory,"CodexLight-migration-"+Guid.NewGuid().ToString("N")+".lnk");try{dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell")??throw new IOException("Shortcut COM unavailable"))!;try{dynamic link=shell.CreateShortcut(temporary);try{link.TargetPath=Path.Combine(r.NewRoot,m.RootStubPath);link.WorkingDirectory=r.NewRoot;link.Description="Codex Light (Velopack migration)";link.Save();}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);}}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}MigrationStorage.Canonical(temporary);File.Move(temporary,path,false);MigrationStorage.AtomicReceipt(Path.Combine(r.Recovery,"shortcut.json"),new{Path=path,Sha256=MigrationCoordinator.Hash(path),Target=Path.Combine(r.NewRoot,m.RootStubPath)});}finally{if(File.Exists(temporary))File.Delete(temporary);}}
 public static void Retire(string receipt,string manifestPath,string manifestHash,string setupHash,bool execute,bool tasksCompleted,bool userApproved){var(r,m)=Inspect(receipt,manifestPath,manifestHash,setupHash);if(!execute){Console.WriteLine("RETIRE INSPECT ONLY: exact old MSI will remain installed.");return;}if(!tasksCompleted||!userApproved)throw new IOException("Separate explicit retirement and completed-task confirmations required");var observation=Read<GuiObservation>(Path.Combine(r.Recovery,"gui-observation.json"));ValidateObservation(observation,MigrationCoordinator.Hash(receipt),manifestHash,MigrationCoordinator.Hash(Path.Combine(r.NewRoot,"current","CodexLight.exe")));
 var initial=Read<DataSnapshot>(Path.Combine(r.Recovery,"data.manifest.json"));if(!initial.SourceRoot.Equals(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CodexLight"),StringComparison.OrdinalIgnoreCase))throw new IOException("Snapshot source outside application data");MigrationStorage.VerifySnapshot(initial,Path.Combine(r.Recovery,"data"));var msiBackup=Path.Combine(r.Recovery,"legacy.msi");if(MigrationCoordinator.Hash(msiBackup)!=r.Legacy.SourceSha256)throw new IOException("Original recovery MSI changed");
 var sid=WindowsIdentity.GetCurrent().User?.Value??throw new IOException("SID absent");var options=new NamedWaitHandleOptions{CurrentUserOnly=true,CurrentSessionOnly=true};using var desktop=new Mutex(true,"CodexLight.Desktop."+sid,options,out bool first);if(!first)throw new IOException("Exit new and old app normally after completing work");try{using var locks=MigrationStorage.AcquireInstallRoots(r.Legacy.InstallRoot,r.NewRoot);SafeStage.Idle(r.Legacy.InstallRoot,r.NewRoot);if(MsiProbe.ReadCurrentUser()!=r.Legacy)throw new IOException("Old MSI changed");var health=SafeStage.Run(Path.Combine(r.NewRoot,"current","CodexLight.exe"),"--backend-health-check");using(var h=JsonDocument.Parse(health.Output)){if(health.Code!=0||!h.RootElement.GetProperty("ok").GetBoolean()||h.RootElement.GetProperty("realAccountVerified").GetBoolean()||!h.RootElement.GetProperty("gracefulShutdown").GetBoolean())throw new IOException("Fresh component health failed");}
 var latest=MigrationStorage.CaptureApplicationData();var backup=Path.Combine(r.Recovery,"pre-retire-data");if(new DriveInfo(Path.GetPathRoot(backup)!).AvailableFreeSpace<MigrationStorage.RequiredBytes(latest,0,0,0))throw new IOException("Insufficient pre-retire backup space");MigrationStorage.CopySnapshot(latest,backup);SafeStage.Idle(r.Legacy.InstallRoot,r.NewRoot);var journal=Path.Combine(r.Recovery,"retirement.json");if(File.Exists(journal))throw new IOException("Retirement journal exists; reconcile previous outcome first");void Save(string phase,string detail)=>MigrationStorage.AtomicReceipt(journal,new{Phase=phase,Detail=detail,StageReceipt=receipt,StageReceiptSha256=MigrationCoordinator.Hash(receipt),Legacy=r.Legacy,NewRoot=r.NewRoot,PreRetireBackup=backup,OriginalMsi=msiBackup});Save("Retiring","Explicit exact-product uninstall; no directory deletion");try{var result=SafeStage.Run(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"msiexec.exe"),"/x",r.Legacy.ProductCode,"/qn","/norestart","/L*v",Path.Combine(r.Recovery,"retire-msi.log"));if(result.Code is 3010 or 1641){Save("RestartRequired","Do not claim completion until post-restart inspection");return;}if(result.Code!=0||!MsiProbe.ExactProductAbsent(r.Legacy.ProductCode))throw new IOException("MSI uninstall not confirmed absent");foreach(var hive in new[]{RegistryHive.CurrentUser,RegistryHive.LocalMachine})foreach(var view in new[]{RegistryView.Registry32,RegistryView.Registry64}){using var baseKey=RegistryKey.OpenBaseKey(hive,view);using var k=baseKey.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\"+r.Legacy.ProductCode);if(k!=null)throw new IOException("Old MSI ARP residue requires review");}SafeStage.VerifyFiles(Path.Combine(r.NewRoot,"current"),m.PayloadFiles,true);SafeStage.Registration(r.NewRoot,m);if(JsonSerializer.Serialize(MigrationStorage.CaptureApplicationData())!=JsonSerializer.Serialize(latest))throw new IOException("Protected data changed during retirement");MigrationStorage.VerifySnapshot(latest,backup);if(MigrationCoordinator.Hash(Path.Combine(r.NewRoot,"Update.exe"))!=m.RootUpdaterSha256||MigrationCoordinator.Hash(SafeStage.Member(r.NewRoot,m.RootStubPath))!=m.RootStubSha256)throw new IOException("Root executables changed during retirement");var postHealth=SafeStage.Run(Path.Combine(r.NewRoot,"current","CodexLight.exe"),"--backend-health-check");using(var post=JsonDocument.Parse(postHealth.Output)){if(postHealth.Code!=0||!post.RootElement.GetProperty("ok").GetBoolean()||post.RootElement.GetProperty("scope").GetString()!="native-and-isolated-demo-backend"||!post.RootElement.GetProperty("gracefulShutdown").GetBoolean())throw new IOException("Post-uninstall health failed");}Save("OldMsiRetired","New app retained, data verified, original source and snapshots retained; shortcut ownership remains separate");}catch(Exception e){Save("RecoveryRequired",e.Message);throw;}
 }finally{desktop.ReleaseMutex();}}
}
